/**
 * 年度爱曲取数（/files/yfps/list20xx.json）。
 */
import { loadJson } from './jsonCache.js'
import { decorateSongMap } from './common.js'

export async function getYfpsList(jsonPath) {
  try {
    const jsonData = await loadJson(jsonPath)
    // 年度爱曲只需要封面，不需要难度配色
    return decorateSongMap(jsonData, [])
  } catch (error) {
    console.error('获取数据失败：', error)
    console.error('实际请求的JSON文件路径：', jsonPath)
    return {}
  }
}
