<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { getYfpsList } from '../../api/yfps.js'
import yfpsCard from '../../components/cards/yfpsCard.vue'
import { ref, onMounted, computed, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const songList = ref({})
const selectedYear = ref('2026')

// 每年主题色只用在选中年份的标签上（其余界面统一走 --dt-* 令牌）
const yearConfig = {
  2020: { color: '#5E5B5E', text: '#FFFFFF', file: '/files/yfps/list2020.json' },
  2021: { color: '#2A3053', text: '#FFFFFF', file: '/files/yfps/list2021.json' },
  2022: { color: '#895C8E', text: '#FFFFFF', file: '/files/yfps/list2022.json' },
  2023: { color: '#7D4751', text: '#FFFFFF', file: '/files/yfps/list2023.json' },
  2024: { color: '#373D52', text: '#ffffff', file: '/files/yfps/list2024.json' },
  2025: { color: '#42469F', text: '#ffffff', file: '/files/yfps/list2025.json' },
  2026: { color: '#C280B0', text: '#ffffff', file: '/files/yfps/list2026.json' },
}

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const tabStyle = (year) => {
  return selectedYear.value === year
    ? { background: yearConfig[year].color, color: yearConfig[year].text }
    : {}
}

const fetchSongData = async () => {
  const filePath = yearConfig[selectedYear.value].file
  const data = await getYfpsList(filePath)
  songList.value = data
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(() => {
  fetchSongData()
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="dt-page">

    <div class="dt-tabs year-tabs">
      <button
        v-for="year in ['2020', '2021', '2022', '2023', '2024', '2025', '2026']"
        :key="year"
        class="dt-tab"
        :class="{ 'dt-tab--active': selectedYear === year, 'is-year-active': selectedYear === year }"
        :style="tabStyle(year)"
        @click="changeYear(year)"
      >
        {{ year }}
      </button>
    </div>

    <div class="card-grid">
      <yfps-card
        v-for="(songItem, songKey) in songList"
        :key="songKey"
        :song-data="songItem"
        :song-key="songKey" @click="openSong(songKey)"
        :main-color="yearColor"
        :text-color="yearTextColor"
      />
    </div>

    <div v-if="!Object.keys(songList).length" class="dt-empty">
      该年份暂无数据
    </div>
  </div>
</template>

<style scoped>
.year-tabs {
  margin-bottom: var(--dt-space-5);
  flex-wrap: wrap;
}

.is-year-active {
  font-weight: 600;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--dt-space-2) var(--dt-space-2);
}

@media (max-width: 900px) {
  .card-grid {
    grid-template-columns: 1fr;
  }
}
</style>
